def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)

    # Find the grid-line color by looking for colors that nearly fill
    # multiple complete rows and columns.
    candidates = []
    for color in colors:
        rows = [r for r in range(h) if sum(x == color for x in grid[r]) >= 0.8 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.8 * h]
        if len(rows) >= 2 and len(cols) >= 2:
            strength = sum(sum(x == color for x in grid[r]) for r in rows)
            strength += sum(sum(grid[r][c] == color for r in range(h)) for c in cols)
            candidates.append((strength, color, rows, cols))

    if not candidates:
        return [[0]]

    _, line_color, rows, cols = max(candidates)
    counts = {}
    for row in grid:
        for x in row:
            if x != line_color:
                counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)

    result = []
    for r in range(len(rows) - 1):
        out_row = []
        for c in range(len(cols) - 1):
            corners = (
                grid[rows[r]][cols[c]],
                grid[rows[r]][cols[c + 1]],
                grid[rows[r + 1]][cols[c]],
                grid[rows[r + 1]][cols[c + 1]],
            )
            if corners[0] != line_color and all(x == corners[0] for x in corners):
                out_row.append(corners[0])
            else:
                out_row.append(background)
        result.append(out_row)

    # Remove only empty outer columns, preserving empty spaces within.
    active = [c for c in range(len(result[0]))
              if any(result[r][c] != background for r in range(len(result)))]
    if active:
        result = [row[min(active):max(active) + 1] for row in result]
    return result
